const { seg, lerp, eo, eio, eob, clamp01 } = kit;
kit.scene('ledger', {
  init(kit) {
    const M = W.MOODS.hallSage;
    const lines = (dx) => [0, 1, 2, 3, 4, 5].map((i) => '<path d="M' + (dx + 18) + ' ' + (-74 + i * 11) + ' h' + (118 - (i % 2) * 30) + '" style="stroke:#8C8577;stroke-width:4;stroke-linecap:round"/>').join('');
    const lectern = '<g class="ledger-lectern" transform="translate(1290 990)"><path d="M-120 0 H120 L90 -26 H-90 Z" style="fill:#B98353;stroke:#2A2522;stroke-width:4;stroke-linejoin:round"/><rect x="-30" y="-330" width="60" height="306" style="fill:#C99A62;stroke:#2A2522;stroke-width:4"/><path d="M-210 -310 L210 -370 L218 -340 L-202 -280 Z" style="fill:#B98353;stroke:#2A2522;stroke-width:4;stroke-linejoin:round"/>' +
      '<g transform="translate(0 -346) rotate(-8)"><path d="M0 4 L-190 14 L-190 2 L0 -6 L190 2 L190 14 Z" style="fill:#8A5D3B;stroke:#2A2522;stroke-width:4"/>' +
      '<path d="M0 0 L-180 8 L-170 -90 L0 -98 Z" style="fill:#FFFDF4;stroke:#2A2522;stroke-width:4;stroke-linejoin:round"/><g transform="translate(-178 0) skewY(-2)">' + lines(0) + '</g>' +
      '<path d="M0 0 L180 8 L170 -90 L0 -98 Z" style="fill:#FFFDF4;stroke:#2A2522;stroke-width:4;stroke-linejoin:round"/>' +
      '<g class="ledger-flip"><path d="M0 0 L180 8 L170 -90 L0 -98 Z" style="fill:#F3ECDC;stroke:#2A2522;stroke-width:4;stroke-linejoin:round"/><g class="ledger-ink">' + lines(4) + '</g></g><path d="M0 -98 V2" style="stroke:#2A2522;stroke-width:4"/></g></g>';
    const q = '<g class="ledger-qpos" transform="translate(1390 470)"><g class="ledger-q"><path d="M-34 -40 Q-34 -88 6 -88 Q46 -88 46 -50 Q46 -20 12 -8 Q0 0 0 20" style="fill:none;stroke:#2A2522;stroke-width:26;stroke-linecap:round"/><path d="M-34 -40 Q-34 -88 6 -88 Q46 -88 46 -50 Q46 -20 12 -8 Q0 0 0 20" style="fill:none;stroke:#F08A7E;stroke-width:16;stroke-linecap:round"/><circle cy="54" r="14" style="fill:#F08A7E;stroke:#2A2522;stroke-width:4"/></g></g>';
    kit.stage.append(kit.h('<div class="ground"><div class="layer ledger-cam"><svg class="art" viewBox="0 0 1920 1080">' +
      W.bg.stoneRoom(M, { seed: 4, floorY: 860 }) + W.prop.window(1640, 560, 1.1, M, true) + W.glow(1640, 380, 420, '#FFF6D8', 0.55) +
      '<ellipse cx="720" cy="996" rx="170" ry="18" style="fill:rgba(42,37,34,.14)"/><ellipse cx="1290" cy="996" rx="150" ry="16" style="fill:rgba(42,37,34,.14)"/>' +
      lectern + W.person('ledger-n', W.NARRATOR) + q + '</svg></div><div class="vignette"></div>' +
      '<p class="hand-label tag ledger-tag" style="left:110px;top:90px">Holy Roman Empire</p></div>'));
    const s = (c) => kit.stage.querySelector(c);
    this.m = W.bindPerson(kit.stage, 'ledger-n');
    Object.assign(this, { cam: s('.ledger-cam'), flip: s('.ledger-flip'), ink: s('.ledger-ink'), q: s('.ledger-q'), qpos: s('.ledger-qpos'), tag: s('.ledger-tag') });
  },
  render(t) {
    this.cam.style.transformOrigin = '1000px 600px';
    this.cam.style.transform = 'scale(' + lerp(1.0, 1.05, eio(seg(t, 0, 5.3))).toFixed(4) + ')';
    // point at the ledger: anticipation, whip, hold, return
    const ant = eio(seg(t, 2.7, 2.92)), hit = eob(seg(t, 2.92, 3.16), 1.6), back = eio(seg(t, 4.5, 4.9));
    const a1 = lerp(lerp(lerp(-8, 10, ant), -95, hit), -8, back);
    const a2 = lerp(lerp(-6, 0, hit), -6, back);
    const a3 = lerp(lerp(14, 180, clamp01(hit)), 14, back);
    const talking = (t > 0.26 && t < 2.7) || (t > 4.16 && t < 4.9);
    const surprised = t > 3.42 && t < 4.16;
    const expr = surprised ? 'surprised' : talking ? (Math.floor(t * 8) % 2 ? 'talk' : 'neutral') : 'neutral';
    const br = Math.sin(t * 2.1) * 1.4;
    W.posePerson(this.m, { x: 700, y: 990, s: 2.6, head: lerp(0, 6, eio(seg(t, 2.6, 2.9))) * (1 - eio(seg(t, 3.42, 3.7))) - 4 * eio(seg(t, 3.5, 3.8)) + br, sq: W.take(t, 3.42),
      expr, blink: W.blinkAt(t, [1.2, 4.95]), a1, a2, a3, b1: 8 - br, lean: br * 0.3 });
    // the page turns over: the next one is blank (lands on 'recorded')
    const fl = eio(seg(t, 2.95, 3.3));
    this.flip.setAttribute('transform', 'scale(' + (1 - 2 * fl).toFixed(3) + ' 1) skewY(' + (-12 * Math.sin(Math.PI * fl)).toFixed(2) + ')');
    this.ink.style.opacity = fl < 0.5 ? 1 : 0;
    W.pop(this.q, t, 3.42, 'bottom');
    this.qpos.setAttribute('transform', 'translate(1390 ' + (470 + 6 * Math.sin(t * 3)).toFixed(1) + ') rotate(' + (5 * Math.sin(t * 2.4)).toFixed(2) + ')');
    W.pop(this.tag, t, 1.9, 'left');
  },
});
